import re,json,os
result={}
for path in ['/bin/integration','/bin/background-worker']:
 try:
  matches=set();tail=b''
  with open(path,'rb') as binary:
   while True:
    block=binary.read(1024*1024)
    if not block:break
    data=tail+block
    matches.update(x.decode('ascii') for x in re.findall(rb'attoparsec[_-]iso8601[!-~]{0,90}',data))
    tail=data[-256:]
  result[path]={'resolved':os.path.realpath(path),'package_strings':sorted(matches)[:12]}
 except OSError as e:result[path]={'unavailable':type(e).__name__}
print(json.dumps(result))
